    case moss
    case wax
    case slate
    case heather
    case ochre
    case peat
    case tide
    case rowan

    var seed: UInt32 {
        switch self {
        case .moss: return 0x4F6F52
        case .wax: return 0xB4472E
        case .slate: return 0x4A6275
        case .heather: return 0x77607F
        case .ochre: return 0xA9741B
        case .peat: return 0x6B5B4B
        case .tide: return 0x2F6F73
        case .rowan: return 0x9A3F52
        }
    }

    var style: String {
        switch self {
        case .moss: return "tonalSpot"
        case .wax: return "tonalSpot"
        case .slate: return "tonalSpot"
        case .heather: return "tonalSpot"
        case .ochre: return "tonalSpot"
        case .peat: return "tonalSpot"
        case .tide: return "tonalSpot"
        case .rowan: return "tonalSpot"
        }
    }

    static let `default` = CroftPreset.moss
}

enum CroftMode: String, CaseIterable, Hashable {
    case light
    case dark
    case pureBlack
}

enum CroftContrast: String, CaseIterable, Hashable {
    case standard
    case medium
    case high

    var level: Double {
        switch self {
        case .standard: return 0
        case .medium: return 0.5
        case .high: return 1
        }
    }
}

