    static let all: [CroftSchemeKey: CroftColorRoles] = {
        var merged: [CroftSchemeKey: CroftColorRoles] = [:]
        for table in [moss, wax, slate, heather, ochre, peat, tide, rowan] {
            merged.merge(table) { current, _ in current }
        }
        return merged
    }()

    static func roles(
        _ preset: CroftPreset,
        _ mode: CroftMode,
        _ contrast: CroftContrast = .standard
    ) -> CroftColorRoles {
        guard let roles = all[CroftSchemeKey(preset: preset, mode: mode, contrast: contrast)] else {
            preconditionFailure("CroftSchemes is missing a preset, mode and contrast combination")
        }
        return roles
    }

    static func colors(
        _ preset: CroftPreset,
        _ mode: CroftMode,
        _ contrast: CroftContrast = .standard
    ) -> CroftColors {
        CroftColors(roles(preset, mode, contrast))
    }
}

/// A spring from tokens.json. SwiftUI takes `response` (2 pi / sqrt(stiffness)) and a damping fraction.
struct CroftSpring {
    let stiffness: Double
    let damping: Double
    let response: Double

    var animation: Animation {
        .spring(response: response, dampingFraction: damping)
    }
}

enum CroftMotion {
    static let spatialFast = CroftSpring(stiffness: Double(CroftTokens.Motion.Spatial.Fast.stiffness), damping: Double(CroftTokens.Motion.Spatial.Fast.damping), response: Double(CroftTokens.Motion.Spatial.Fast.swiftUIResponse))
    static let spatialDefault = CroftSpring(stiffness: Double(CroftTokens.Motion.Spatial.Default.stiffness), damping: Double(CroftTokens.Motion.Spatial.Default.damping), response: Double(CroftTokens.Motion.Spatial.Default.swiftUIResponse))
    static let spatialSlow = CroftSpring(stiffness: Double(CroftTokens.Motion.Spatial.Slow.stiffness), damping: Double(CroftTokens.Motion.Spatial.Slow.damping), response: Double(CroftTokens.Motion.Spatial.Slow.swiftUIResponse))
    static let effectsFast = CroftSpring(stiffness: Double(CroftTokens.Motion.Effects.Fast.stiffness), damping: Double(CroftTokens.Motion.Effects.Fast.damping), response: Double(CroftTokens.Motion.Effects.Fast.swiftUIResponse))
    static let effectsDefault = CroftSpring(stiffness: Double(CroftTokens.Motion.Effects.Default.stiffness), damping: Double(CroftTokens.Motion.Effects.Default.damping), response: Double(CroftTokens.Motion.Effects.Default.swiftUIResponse))
    static let effectsSlow = CroftSpring(stiffness: Double(CroftTokens.Motion.Effects.Slow.stiffness), damping: Double(CroftTokens.Motion.Effects.Slow.damping), response: Double(CroftTokens.Motion.Effects.Slow.swiftUIResponse))
    static let reducedSpatialFast = CroftSpring(stiffness: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Fast.stiffness), damping: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Fast.damping), response: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Fast.swiftUIResponse))
    static let reducedSpatialDefault = CroftSpring(stiffness: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Default.stiffness), damping: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Default.damping), response: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Default.swiftUIResponse))
    static let reducedSpatialSlow = CroftSpring(stiffness: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Slow.stiffness), damping: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Slow.damping), response: Double(CroftTokens.Motion.StandardSpatialForReducedMotion.Slow.swiftUIResponse))
